-- Unidad 6 · Serie 6. Consignas conservadas del Markdown recibido; resoluciones nuevas y teoría cotejada con las cuatro presentaciones.
begin;
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'ruta-de-la-unidad','chapter',$cbc$1. Ruta de la unidad$cbc$,10,$cbc$<p class="u6Lead">Partí de Lewis. La geometría te permite decidir la polaridad; la polaridad y el tamaño explican las interacciones; las interacciones ayudan a predecir propiedades.</p><div class="u6Route"><span>Lewis</span><b>→</b><span>GE y GM</span><b>→</b><span>Dipolos</span><b>→</b><span>Interacciones</span><b>→</b><span>Propiedades</span></div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Pregunta</th><th>Mirada útil</th><th>Resultado</th></tr></thead><tbody><tr><td>¿Dónde están los electrones?</td><td>Lewis y pares libres</td><td>AXₘEₙ</td></tr><tr><td>¿Qué forma tiene?</td><td>Zonas alrededor del centro</td><td>Geometría y ángulo</td></tr><tr><td>¿Se anulan los dipolos?</td><td>Vectores y simetría</td><td>Polar o apolar</td></tr><tr><td>¿Qué atrae las partículas?</td><td>London, dipolo, puente H o red</td><td>Ebullición, solubilidad, conducción</td></tr></tbody></table></div><div class="u6Sources"><strong>Material original de la cátedra</strong><div><a href="./assets/chemistry/unit-06/5.3%20Geometr%C3%ADa%20molecular.pdf" target="_blank" rel="noopener">Geometría molecular ↗</a><a href="./assets/chemistry/unit-06/5.4%20Polaridad%20de%20mol%C3%A9culas.pdf" target="_blank" rel="noopener">Polaridad de moléculas ↗</a><a href="./assets/chemistry/unit-06/5.5%20Interacciones%20intermoleculares.pdf" target="_blank" rel="noopener">Interacciones intermoleculares ↗</a><a href="./assets/chemistry/unit-06/5.6%20Tabla%20de%20propiedades.pdf" target="_blank" rel="noopener">Tabla de propiedades ↗</a></div></div>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'lewis-y-trepev','chapter',$cbc$2. Lewis y los cuatro postulados TRePEV$cbc$,20,$cbc$<p class="u6Lead">La fórmula dice cuántos átomos hay; Lewis agrega conectividad y electrones de valencia. Para obtener la forma espacial hay que distribuir las zonas de electrones alrededor del átomo central.</p><ol class="u6Rules"><li>Los electrones de valencia se representan en pares enlazantes o libres.</li><li>Las zonas de electrones se separan para minimizar la repulsión.</li><li>Un par libre ocupa más espacio y repele más que uno enlazante.</li><li>Un enlace doble o triple cuenta como <strong>un dominio</strong> a efectos de la geometría.</li></ol><div class="u6Step"><span>1</span><div><h4>Dibujá Lewis</h4><p>Contá electrones de valencia, elegí átomo central, completá enlaces, pares libres y cargas formales. Para un ion, sumá electrones si es negativo o restalos si es positivo.</p></div></div><div class="u6Step"><span>2</span><div><h4>Contá dominios</h4><p>Sumá enlaces alrededor del centro y pares libres del centro. No cuentes cada raya de un doble enlace por separado.</p></div></div><div class="u6Step"><span>3</span><div><h4>Separá GE de GM</h4><p>La geometría electrónica (GE) ubica todas las zonas; la molecular (GM) describe la posición de los núcleos. En iones, hablamos de geometría del ion.</p></div></div><aside class="u6Tip"><strong>Para recordar:</strong> Un dibujo plano de Lewis no muestra por sí solo el ángulo tridimensional.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'geometrias-y-angulos','chapter',$cbc$3. Geometrías y ángulos$cbc$,30,$cbc$<p class="u6Lead">En AXₘEₙ, X son los átomos unidos al centro A y E son los pares libres del centro.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Dominios</th><th>AXₘEₙ</th><th>GE</th><th>GM o geometría del ion</th><th>Ángulo orientativo</th><th>Ejemplo</th></tr></thead><tbody><tr><td>2</td><td>AX₂</td><td>lineal</td><td>lineal</td><td>180°</td><td>CO₂, CS₂</td></tr><tr><td>3</td><td>AX₃</td><td>triangular plana</td><td>triangular plana</td><td>120°</td><td>BF₃, SO₃, CO₃²⁻</td></tr><tr><td>3</td><td>AX₂E</td><td>triangular plana</td><td>angular</td><td>menor que 120°</td><td>SO₂</td></tr><tr><td>4</td><td>AX₄</td><td>tetraédrica</td><td>tetraédrica</td><td>109,5°</td><td>CH₄, SO₄²⁻, NH₄⁺</td></tr><tr><td>4</td><td>AX₃E</td><td>tetraédrica</td><td>piramidal trigonal</td><td>menor que 109,5°</td><td>NH₃, PH₃, SO₃²⁻</td></tr><tr><td>4</td><td>AX₂E₂</td><td>tetraédrica</td><td>angular</td><td>menor que 109,5°</td><td>H₂O, H₂S, Cl₂O</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> Los valores 120° y 109,5° son ideales para zonas equivalentes. NH₃ mide ≈107°, H₂O ≈104,5° y H₂S ≈92°. Átomos periféricos distintos también distorsionan ángulos, como en CH₂O o CHCl₃.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'iones-y-geometria','chapter',$cbc$4. Geometría de iones poliatómicos$cbc$,40,$cbc$<p class="u6Lead">El procedimiento TRePEV también funciona en iones. La carga cambia el conteo total de electrones de Lewis; luego contás dominios del átomo central.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Ion</th><th>Centro</th><th>Dominios y pares libres</th><th>Forma</th></tr></thead><tbody><tr><td>NO₃⁻</td><td>N</td><td>3 enlaces, 0 pares libres</td><td>triangular plana</td></tr><tr><td>CO₃²⁻</td><td>C</td><td>3 enlaces, 0 pares libres</td><td>triangular plana</td></tr><tr><td>SO₄²⁻</td><td>S</td><td>4 enlaces, 0 pares libres</td><td>tetraédrica</td></tr><tr><td>PO₄³⁻</td><td>P</td><td>4 enlaces, 0 pares libres</td><td>tetraédrica</td></tr><tr><td>SO₃²⁻</td><td>S</td><td>3 enlaces, 1 par libre</td><td>piramidal trigonal</td></tr><tr><td>NH₄⁺</td><td>N</td><td>4 enlaces, 0 pares libres</td><td>tetraédrica</td></tr><tr><td>BrO₂⁻</td><td>Br</td><td>2 enlaces, 2 pares libres</td><td>angular</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> El ion nitrato tiene resonancia, pero los tres enlaces N–O siguen definiendo tres dominios.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'polaridad-y-vectores','chapter',$cbc$5. De la geometría a la polaridad$cbc$,50,$cbc$<p class="u6Lead">Un enlace puede ser polar porque los átomos atraen de manera distinta los electrones. La molécula completa será polar si la suma vectorial no se anula.</p><div class="u6Equation"><div class="u6Math" data-latex="%5Cvec%7B%5Cmu%7D_%7B%5Cmathrm%7Btotal%7D%7D%3D%5Csum_i%5Cvec%7B%5Cmu%7D_%7Bi%7D" data-display="true"></div></div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Caso</th><th>Qué pasa con los vectores</th><th>Resultado</th></tr></thead><tbody><tr><td>H₂ o N₂</td><td>Unión entre átomos idénticos</td><td>apolar</td></tr><tr><td>HF</td><td>Un enlace polar</td><td>polar</td></tr><tr><td>CO₂ o CS₂</td><td>Dos vectores iguales y opuestos a 180°</td><td>apolar</td></tr><tr><td>BF₃ o SO₃</td><td>Tres vectores equivalentes a 120°</td><td>apolar</td></tr><tr><td>CH₄ o CCl₄</td><td>Cuatro vectores equivalentes tetraédricos</td><td>apolar</td></tr><tr><td>H₂O, NH₃, SO₂</td><td>Pares libres y forma asimétrica</td><td>polar</td></tr><tr><td>CHCl₃</td><td>Ligandos distintos; vectores no se compensan</td><td>polar</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> La regla “sin pares libres y ligandos iguales” es un atajo para estas geometrías, no un teorema universal. Revisá la suma de dipolos si la estructura es más compleja o tiene varios centros.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'london-y-polarizabilidad','chapter',$cbc$6. Fuerzas de London y polarizabilidad$cbc$,60,$cbc$<p class="u6Lead">London está presente entre todas las partículas; es la única interacción intermolecular entre moléculas apolares.</p><p>La nube electrónica fluctúa, crea un dipolo instantáneo e induce otro en una partícula vecina. <strong>Polarizabilidad</strong> es la facilidad con que se deforma esa nube.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Comparación</th><th>Razón de la diferencia</th></tr></thead><tbody><tr><td>H₂ frente a Cl₂</td><td>Cl₂ tiene más electrones y una nube más polarizable.</td></tr><tr><td>Cl₂, Br₂, I₂</td><td>London aumenta al crecer la nube; también aumenta el punto de ebullición.</td></tr><tr><td>Isómeros lineales y ramificados</td><td>La forma y el área de contacto modifican London.</td></tr><tr><td>CH₄, SiH₄, GeH₄, SnH₄</td><td>Al bajar en el grupo aumenta el número de electrones y el punto de ebullición.</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> No uses la masa molar como fuerza en sí: la explicación física es la polarizabilidad y el contacto.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'dipolos-y-puentes','chapter',$cbc$7. Dipolo–dipolo y puente de hidrógeno$cbc$,70,$cbc$<p class="u6Lead">Las moléculas polares suman atracciones dipolo–dipolo a London. Algunas, además, forman puentes de hidrógeno.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Interacción</th><th>Cuándo aparece</th><th>Ejemplos</th></tr></thead><tbody><tr><td>Dipolo–dipolo</td><td>Entre dipolos permanentes de moléculas polares.</td><td>HCl, HBr, SO₂, CHCl₃</td></tr><tr><td>Puente de hidrógeno en sustancia pura</td><td>H enlazado directamente a N, O o F y un aceptor con par libre.</td><td>NH₃, H₂O, HF</td></tr><tr><td>Puente de H con agua</td><td>El agua puede donar H a un O, N o F aceptor, aunque el soluto no tenga H–O/H–N/H–F.</td><td>éteres, cetonas, aminas; según tamaño y estructura</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> No alcanza con que una molécula tenga H. HBr no forma los puentes de H típicos de NH₃, H₂O o HF.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'ebullicion-y-comparaciones','chapter',$cbc$8. Cómo comparar puntos de ebullición$cbc$,80,$cbc$<p class="u6Lead">Al hervir una sustancia molecular se separan moléculas: vencés atracciones entre ellas, no cortás los enlaces covalentes internos.</p><div class="u6Step"><span>1</span><div><h4>Identificá partículas</h4><p>Ion–ion en una red, enlace metálico en un metal o moléculas/átomos neutros en una sustancia molecular o gas noble.</p></div></div><div class="u6Step"><span>2</span><div><h4>Compará interacciones</h4><p>Entre moléculas: todas tienen London; sumá dipolo–dipolo si son polares y puente de H cuando corresponda.</p></div></div><div class="u6Step"><span>3</span><div><h4>Controlá el tamaño</h4><p>Si cambian mucho los electrones o la superficie, London puede dominar una comparación entre moléculas de distinta polaridad.</p></div></div><div class="u6Equation"><div class="u6Math" data-latex="%5Cmathrm%7BCH_4%3CSiH_4%3CH_2S%3CKCl%7D" data-display="true"></div></div><p>En este ejemplo, CH₄ tiene 10 electrones; SiH₄ y H₂S tienen 18, pero H₂S suma dipolo–dipolo. KCl forma una red iónica.</p><aside class="u6Tip"><strong>Para recordar:</strong> No existe un ranking absoluto de fuerzas que sirva sin mirar tamaño y tipo de partícula. NH₃, H₂O y HF muestran puntos de ebullición altos para su grupo por sus puentes de H.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'solubilidad','chapter',$cbc$9. Solubilidad: interacciones nuevas$cbc$,90,$cbc$<p class="u6Lead">Una disolución depende de la competencia entre soluto–soluto, solvente–solvente y soluto–solvente. “Lo semejante disuelve a lo semejante” es una primera pista.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Soluto y solvente</th><th>Interacción relevante</th><th>Qué revisar</th></tr></thead><tbody><tr><td>Molécula polar + agua</td><td>dipolo–dipolo; a veces puente de H</td><td>tamaño de la parte apolar</td></tr><tr><td>Molécula apolar + solvente apolar</td><td>London</td><td>polarizabilidad y contacto</td></tr><tr><td>Sal + agua</td><td>ion–dipolo, hidratación</td><td>energía de red frente a hidratación</td></tr><tr><td>Sal + solvente apolar</td><td>no hay hidratación ion–dipolo eficaz</td><td>suele disolver poco</td></tr></tbody></table></div><p>El agua orienta el oxígeno parcialmente negativo hacia cationes y sus hidrógenos parcialmente positivos hacia aniones. Etanol y agua son miscibles; compuestos orgánicos con O o N pueden aceptar puentes de H si la parte apolar no domina.</p><aside class="u6Tip"><strong>Para recordar:</strong> “Iónico = soluble en agua” y “polar = siempre soluble” son simplificaciones: AgCl es poco soluble y una cadena hidrocarbonada larga reduce la solubilidad.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'tipos-de-sustancias','chapter',$cbc$10. Red iónica, moléculas y metales$cbc$,100,$cbc$<p class="u6Lead">La propiedad eléctrica depende de cargas móviles. La temperatura de fusión depende de las atracciones que hay que vencer.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Propiedad</th><th>Iónica</th><th>Molecular</th><th>Metálica</th></tr></thead><tbody><tr><td>Partículas</td><td>cationes y aniones en red</td><td>moléculas discretas</td><td>átomos con electrones deslocalizados</td></tr><tr><td>Fusión</td><td>a menudo alta; romper red</td><td>variable, a menudo menor; separar moléculas</td><td>variable; vencer cohesión metálica</td></tr><tr><td>Conducción sólida</td><td>no: iones fijos</td><td>por lo general no</td><td>sí: electrones móviles</td></tr><tr><td>Conducción fundida</td><td>sí: iones móviles</td><td>por lo general no</td><td>sí</td></tr><tr><td>Agua</td><td>algunas sales se hidratan y disuelven</td><td>depende de polaridad, puente H y tamaño</td><td>habitualmente no se disuelven como moléculas</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> No confundas sustancias moleculares con redes covalentes como diamante o SiO₂; éstas no son conjuntos de moléculas discretas. El mercurio es una excepción líquida a temperatura ambiente.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'preguntas-de-estudio','chapter',$cbc$11. Preguntas de estudio$cbc$,110,$cbc$<p class="u6Lead">Primero intentá responder sin abrir la explicación. Las dos primeras preguntas son de la guía 1; las seis siguientes, de la guía 2.</p><details class="u6Subsolution"><summary>Geometría · ¿Qué dice TRePEV?</summary><div><p>Los dominios del átomo central se repelen y se disponen con separación máxima. Dibujá Lewis, contá los enlaces como un dominio cada uno y sumá pares libres; obtené GE y luego GM.</p></div></details><details class="u6Subsolution"><summary>Polaridad · ¿Cómo se decide?</summary><div><p>Marcá la dirección de cada dipolo de enlace y sumalos según la forma tridimensional. Si se cancelan, la molécula es apolar; si queda resultante, polar.</p></div></details><details class="u6Subsolution"><summary>¿Qué son las interacciones intermoleculares?</summary><div><p>Atracciones entre partículas distintas, decisivas para la separación durante fusión y ebullición. Entre moléculas: London siempre; dipolo–dipolo si hay dipolo permanente; puente de H cuando corresponde.</p></div></details><details class="u6Subsolution"><summary>¿Qué es polarizabilidad?</summary><div><p>La facilidad para deformar la nube electrónica. Cuanto mayor, más intensos suelen ser los dipolos inducidos y London.</p></div></details><details class="u6Subsolution"><summary>¿Qué relación tienen con ebullición?</summary><div><p>A igualdad de otras condiciones, atracciones más intensas requieren más energía para separar las partículas y elevan el punto de ebullición.</p></div></details><details class="u6Subsolution"><summary>¿Cómo predigo solubilidad?</summary><div><p>Compará las interacciones soluto–solvente nuevas con las que se deben vencer en soluto y solvente. Incluí ion–dipolo para sales con agua y el efecto de la porción apolar.</p></div></details><details class="u6Subsolution"><summary>¿Por qué pueden disolverse sales en agua?</summary><div><p>El agua hidrata los iones por ion–dipolo. La disolución es favorable solo si la compensación energética y entrópica alcanza para vencer la red, por eso no todas las sales son solubles.</p></div></details><details class="u6Subsolution"><summary>¿Qué distingue iónico, molecular y metálico?</summary><div><p>Red de iones, moléculas discretas y red con electrones móviles, respectivamente. Esa estructura explica fusión y conducción.</p></div></details>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
insert into public.course_sections(subject,unit_no,section_key,section_type,title,sort_order,body_html,is_public) values ('chemistry',6,'protocolo-de-examen','chapter',$cbc$12. Protocolo para resolver la serie$cbc$,120,$cbc$<p class="u6Lead">Usá esta lista cuando la consigna mezcle geometría, dipolos y propiedades.</p><div class="u6Step"><span>1</span><div><h4>Lewis</h4><p>Contá electrones y pares libres, verificá la carga.</p></div></div><div class="u6Step"><span>2</span><div><h4>TRePEV</h4><p>Contá dominios, anotá AXₘEₙ, GE, GM y ángulo.</p></div></div><div class="u6Step"><span>3</span><div><h4>Polaridad</h4><p>Identificá enlaces polares y sumá vectores en el espacio.</p></div></div><div class="u6Step"><span>4</span><div><h4>Interacción</h4><p>London siempre; sumá dipolo–dipolo o puente de H si corresponde.</p></div></div><div class="u6Step"><span>5</span><div><h4>Propiedad</h4><p>Compará tipo de partícula, tamaño, polarizabilidad, movilidad de carga y solvente.</p></div></div><aside class="u6Tip"><strong>Para recordar:</strong> Para examenes con opciones, descartá primero “sustancia iónica” cuando se pide molécula; luego revisá geometría y dipolos.</aside>$cbc$,false) on conflict(subject,unit_no,section_key) do update set section_type=excluded.section_type,title=excluded.title,sort_order=excluded.sort_order,body_html=excluded.body_html,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.1$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Para describir una geometría molecular, los químicos utilizan las longitudes y los ángulos de enlace. Para referirse a las longitudes de enlace, deben indicarse dos átomos adyacentes; para referirse a los ángulos de enlace, se deben indicar tres átomos contiguos. Por ejemplo, para el caso del metano (<span class="u6Math" data-latex="CH_4" data-display="false"></span>): longitud de enlace <span class="u6Math" data-latex="C-H%20%3D%20109%5Ctext%7B%20pm%7D" data-display="false"></span>; ángulo de enlace <span class="u6Math" data-latex="H%5Chat%7BC%7DH%20%3D%20109%2C5%5E%5Ccirc" data-display="false"></span>. Predecir la geometría de las moléculas siguientes según la TRePEV e indicar el valor aproximado de los ángulos de enlace según se indica en cada caso: a) 1) <span class="u6Math" data-latex="H_2S%2C%20H%5Chat%7BS%7DH" data-display="false"></span>; 2) <span class="u6Math" data-latex="OSO%2C%20O%5Chat%7BS%7DO" data-display="false"></span>; 3) <span class="u6Math" data-latex="SO_3%2C%20O%5Chat%7BS%7DO" data-display="false"></span>; b) 1) <span class="u6Math" data-latex="CO_2%2C%20O%5Chat%7BC%7DO" data-display="false"></span>; 2) <span class="u6Math" data-latex="CHCl_3%2C%20H%5Chat%7BC%7DCl" data-display="false"></span>; 3) <span class="u6Math" data-latex="CH_4" data-display="false"></span>; c) 1) <span class="u6Math" data-latex="BF_3%2C%20F%5Chat%7BB%7DF" data-display="false"></span>; 2) <span class="u6Math" data-latex="NH_3%2C%20H%5Chat%7BN%7DH" data-display="false"></span>; 3) <span class="u6Math" data-latex="SiH_4%2C%20H%5Chat%7BS%7DiH" data-display="false"></span>.</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',10,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Contá dominios en el centro. Los pares libres cambian la forma y comprimen los ángulos; los valores ideales son una referencia, no una medida exacta.</p><details class="u6Subsolution" open><summary>a) H₂S, SO₂ y SO₃</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Molécula</th><th>Lewis / AXₘEₙ</th><th>GE → GM</th><th>Ángulo pedido</th></tr></thead><tbody><tr><td>H₂S</td><td>S con dos enlaces S–H y dos pares libres · AX₂E₂</td><td>tetraédrica → angular</td><td>H–S–H ≈ 92°</td></tr><tr><td>SO₂ (OSO)</td><td>S con dos enlaces S–O y un par libre · AX₂E</td><td>triangular plana → angular</td><td>O–S–O ≈ 119° (menor que 120°)</td></tr><tr><td>SO₃</td><td>S con tres zonas S–O, ningún par libre · AX₃</td><td>triangular plana → triangular plana</td><td>O–S–O = 120°</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> El resumen recibido aproximaba H₂S a 109,5°. Ese es el ángulo ideal tetraédrico de las zonas electrónicas; el ángulo H–S–H observado es cercano a 92°.</aside></div></details><details class="u6Subsolution"><summary>b) CO₂, CHCl₃ y CH₄</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Molécula</th><th>Dominios en C</th><th>Forma</th><th>Ángulo pedido</th></tr></thead><tbody><tr><td>CO₂</td><td>2 dobles enlaces = 2 dominios · AX₂</td><td>lineal</td><td>O–C–O = 180°</td></tr><tr><td>CHCl₃</td><td>4 enlaces simples · AX₄</td><td>tetraédrica distorsionada</td><td>H–C–Cl ≈ 109,5° como estimación TRePEV</td></tr><tr><td>CH₄</td><td>4 enlaces C–H iguales · AX₄</td><td>tetraédrica</td><td>H–C–H = 109,5°</td></tr></tbody></table></div><p>En CHCl₃, H y Cl son distintos: los ángulos reales no son todos idénticos.</p></div></details><details class="u6Subsolution"><summary>c) BF₃, NH₃ y SiH₄</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Molécula</th><th>Centro y AXₘEₙ</th><th>Forma</th><th>Ángulo pedido</th></tr></thead><tbody><tr><td>BF₃</td><td>B: 3 enlaces y 0 pares · AX₃</td><td>triangular plana</td><td>F–B–F = 120°</td></tr><tr><td>NH₃</td><td>N: 3 enlaces y 1 par · AX₃E</td><td>piramidal trigonal</td><td>H–N–H ≈ 107°</td></tr><tr><td>SiH₄</td><td>Si: 4 enlaces y 0 pares · AX₄</td><td>tetraédrica</td><td>H–Si–H = 109,5°</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> La grafía HŜiH de la consigna se conserva tal cual llegó; el átomo central de SiH₄ es Si.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.2$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Poner en correspondencia los pares siguientes en base a la TRePEV: <span class="u6Math" data-latex="CS_2" data-display="false"></span> ----- piramidal <span class="u6Math" data-latex="NH_3" data-display="false"></span> ----- angular <span class="u6Math" data-latex="H_2O" data-display="false"></span> ----- lineal ¿Cuál/es es/son moléculas polares (<span class="u6Math" data-latex="%5Cmu%20%5Cneq%200" data-display="false"></span>) y cuál/es es/son no polares (<span class="u6Math" data-latex="%5Cmu%20%3D%200" data-display="false"></span>)? Justificar.</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',20,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Emparejá la forma mediante AXₘEₙ; después sumá los dipolos, sin confundir enlace polar con molécula polar.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Molécula</th><th>Centro y dominios</th><th>Geometría correcta</th><th>Polaridad</th></tr></thead><tbody><tr><td>CS₂</td><td>C: dos dobles enlaces, 0 pares · AX₂</td><td>lineal</td><td>apolar: dipolos C–S opuestos se cancelan</td></tr><tr><td>NH₃</td><td>N: 3 enlaces, 1 par · AX₃E</td><td>piramidal</td><td>polar: resultante distinta de cero</td></tr><tr><td>H₂O</td><td>O: 2 enlaces, 2 pares · AX₂E₂</td><td>angular</td><td>polar: resultante hacia O</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> Las geometrías de la consigna están deliberadamente desordenadas: CS₂ → lineal; NH₃ → piramidal; H₂O → angular.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.3$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Predecir, en base a la TRePEV, la geometría de las moléculas siguientes: a) <span class="u6Math" data-latex="PH_3" data-display="false"></span>; b) <span class="u6Math" data-latex="CCl_4" data-display="false"></span>; c) <span class="u6Math" data-latex="Cl_2O" data-display="false"></span>. ¿Cuál/es tiene/n momento dipolar distinto de cero?</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',30,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">El par libre modifica la forma; luego compará si los dipolos de los enlaces se cancelan.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Molécula</th><th>Lewis / centro</th><th>Geometría</th><th>Dipolo resultante</th></tr></thead><tbody><tr><td>PH₃</td><td>P: tres P–H y un par libre · AX₃E</td><td>piramidal</td><td>pequeño, pero distinto de cero</td></tr><tr><td>CCl₄</td><td>C: cuatro C–Cl, sin pares · AX₄</td><td>tetraédrica simétrica</td><td>cero: cuatro dipolos iguales se cancelan</td></tr><tr><td>Cl₂O</td><td>O central: dos O–Cl y dos pares · AX₂E₂</td><td>angular</td><td>distinto de cero</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> Respuesta: PH₃ y Cl₂O. En PH₃ el dipolo experimental es pequeño; la geometría piramidal sola no indica su intensidad.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.4$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Aplicando la TRePEV, determinar la geometría de los iones poliatómicos siguientes: a) <span class="u6Math" data-latex="SO_4%5E%7B2-%7D" data-display="false"></span>; b) <span class="u6Math" data-latex="CO_3%5E%7B2-%7D" data-display="false"></span>; c) <span class="u6Math" data-latex="PO_4%5E%7B3-%7D" data-display="false"></span>; d) <span class="u6Math" data-latex="SO_3%5E%7B2-%7D" data-display="false"></span>; e) <span class="u6Math" data-latex="NH_4%5E%2B" data-display="false"></span>.</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',40,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">En cada ion, dibujá Lewis con la carga y contá enlaces y pares libres del átomo central. La resonancia no añade dominios.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Ion</th><th>Centro</th><th>Dominios / AXₘEₙ</th><th>Geometría del ion</th><th>Ángulo orientativo</th></tr></thead><tbody><tr><td>SO₄²⁻</td><td>S</td><td>4 enlaces, 0 pares · AX₄</td><td>tetraédrica</td><td>≈109,5°</td></tr><tr><td>CO₃²⁻</td><td>C</td><td>3 enlaces, 0 pares · AX₃</td><td>triangular plana</td><td>120°</td></tr><tr><td>PO₄³⁻</td><td>P</td><td>4 enlaces, 0 pares · AX₄</td><td>tetraédrica</td><td>≈109,5°</td></tr><tr><td>SO₃²⁻</td><td>S</td><td>3 enlaces, 1 par · AX₃E</td><td>piramidal trigonal</td><td>menor que 109,5°</td></tr><tr><td>NH₄⁺</td><td>N</td><td>4 enlaces, 0 pares · AX₄</td><td>tetraédrica</td><td>≈109,5°</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> En SO₃²⁻ el S conserva un par libre. En NH₄⁺, el N usa sus cuatro enlaces y no conserva par libre.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.5$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Indicar cuál de las siguientes moléculas presenta ángulos de enlace de <span class="u6Math" data-latex="120%5E%5Ccirc" data-display="false"></span> según la TRePEV: (a) <span class="u6Math" data-latex="H%3A%5Cunderset%7B%5Cddot%7BH%7D%7D%7B%5Coverset%7B%5Cddot%7BN%7D%7D%7B..%7D%7D%3AH" data-display="false"></span> (b) <span class="u6Math" data-latex="%3AS%3A%3AC%3A%3AS%3A" data-display="false"></span> (c) <span class="u6Math" data-latex="%3A%5Cunderset%7B%5Cddot%7B..%7D%7D%7BBr%7D%3A%5Cunderset%7B%5Coverset%7B%5Cddot%7B..%7D%7D%7B%3ABr%3A%7D%7D%7B%5Coverset%7B%5Cddot%7B..%7D%7D%7BB%7D%7D%3A%5Cunderset%7B%5Cddot%7B..%7D%7D%7BBr%7D%3A" data-display="false"></span> (d) <span class="u6Math" data-latex="H%3A%5Cddot%7BS%7D%3AH" data-display="false"></span> Justificar en no más de página y media y consultar al docente que sea correcto. Problema de examen de la Cátedra - 2024.</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',50,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Leé primero qué molécula representa cada estructura de Lewis de las opciones. Después contá zonas del átomo central.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Opción</th><th>Especie identificada</th><th>AXₘEₙ</th><th>Ángulo</th></tr></thead><tbody><tr><td>(a)</td><td>NH₃</td><td>AX₃E</td><td>≈107°</td></tr><tr><td>(b)</td><td>CS₂</td><td>AX₂</td><td>180°</td></tr><tr><td>(c)</td><td>BBr₃</td><td>AX₃</td><td>120°</td></tr><tr><td>(d)</td><td>H₂S</td><td>AX₂E₂</td><td>≈92°</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> <strong>Correcta: (c), BBr₃.</strong> B queda con tres enlaces y sin par libre: los tres Br ocupan vértices de una geometría triangular plana. El 109,5° del borrador para H₂S era solo el ideal tetraédrico.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-geometria',$cbc$Ejercicio 6.6$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Indicar cuál es la molécula no polar que presenta enlaces polares: (a) <span class="u6Math" data-latex="K_2O" data-display="false"></span>; (b) <span class="u6Math" data-latex="NH_3" data-display="false"></span>; (c) <span class="u6Math" data-latex="SeO_3" data-display="false"></span>; (d) <span class="u6Math" data-latex="N_2" data-display="false"></span>. Justificar en no más de media página y consultar al docente que sea correcto. Problema de examen de la Cátedra - 2023.</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',60,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Una opción debe ser una molécula, tener enlaces polares y aun así cancelar sus dipolos por simetría.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Opción</th><th>Análisis</th><th>¿Cumple?</th></tr></thead><tbody><tr><td>K₂O</td><td>red iónica, no molécula discreta</td><td>no</td></tr><tr><td>NH₃</td><td>enlaces N–H polares; geometría piramidal polar</td><td>no</td></tr><tr><td>SeO₃</td><td>enlaces Se–O polares; tres dominios simétricos, triangular plana</td><td>sí</td></tr><tr><td>N₂</td><td>molécula apolar, pero enlace N–N apolar</td><td>no</td></tr></tbody></table></div><div class="u6Equation"><div class="u6Math" data-latex="%5Cvec%7B%5Cmu%7D_%7B%5Cmathrm%7BSeO_3%7D%7D%3D%5Cvec%7B%5Cmu%7D_1%2B%5Cvec%7B%5Cmu%7D_2%2B%5Cvec%7B%5Cmu%7D_3%3D0" data-display="true"></div></div><aside class="u6Tip"><strong>Para recordar:</strong> <strong>Correcta: (c), SeO₃.</strong> Los tres vectores equivalentes a 120° se anulan.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.7$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><ol type="a">
<li>¿Qué tipos de interacciones existirán entre las moléculas de las sustancias siguientes? <span class="u6Math" data-latex="CCl_4" data-display="false"></span>; <span class="u6Math" data-latex="CHCl_3" data-display="false"></span>; <span class="u6Math" data-latex="SO_3" data-display="false"></span>; <span class="u6Math" data-latex="BCl_3" data-display="false"></span>; <span class="u6Math" data-latex="SO_2" data-display="false"></span>; <span class="u6Math" data-latex="HF" data-display="false"></span>; <span class="u6Math" data-latex="HBr" data-display="false"></span>; <span class="u6Math" data-latex="H_2O" data-display="false"></span>. Justificar considerando el tipo de interacciones intermoleculares involucradas.</li>
</ol></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',70,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">London está siempre presente. Sumá dipolo–dipolo si la molécula es polar; sumá puente de H entre moléculas puras cuando hay H unido a N, O o F.</p><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Sustancia</th><th>Forma / polaridad</th><th>Interacciones entre sus moléculas</th></tr></thead><tbody><tr><td>CCl₄</td><td>tetraédrica simétrica · apolar</td><td>London</td></tr><tr><td>CHCl₃</td><td>tetraédrica con ligandos distintos · polar</td><td>London + dipolo–dipolo</td></tr><tr><td>SO₃</td><td>triangular plana simétrica · apolar</td><td>London</td></tr><tr><td>BCl₃</td><td>triangular plana simétrica · apolar</td><td>London</td></tr><tr><td>SO₂</td><td>angular · polar</td><td>London + dipolo–dipolo</td></tr><tr><td>HF</td><td>polar, H–F</td><td>London + dipolo–dipolo + puente de H</td></tr><tr><td>HBr</td><td>polar, H–Br</td><td>London + dipolo–dipolo</td></tr><tr><td>H₂O</td><td>angular, H–O</td><td>London + dipolo–dipolo + puente de H</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> No marques puente de H para HBr: el H no está enlazado a N, O ni F.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.8$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Poner en correspondencia las sustancias siguientes con sus puntos de ebullición respectivos. Justificar: a) <span class="u6Math" data-latex="NH_3" data-display="false"></span> ----- <span class="u6Math" data-latex="-185%2C8%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span> <span class="u6Math" data-latex="H_2" data-display="false"></span> ----- <span class="u6Math" data-latex="-33%2C3%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span> <span class="u6Math" data-latex="N_2" data-display="false"></span> ----- <span class="u6Math" data-latex="-252%2C8%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span> b) <span class="u6Math" data-latex="SiH_4" data-display="false"></span> ----- <span class="u6Math" data-latex="-161%2C5%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span> <span class="u6Math" data-latex="CH_4" data-display="false"></span> ----- <span class="u6Math" data-latex="-112%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span> <span class="u6Math" data-latex="AsH_3" data-display="false"></span> ----- <span class="u6Math" data-latex="-62%2C5%5Ctext%7B%20%7D%5E%5Ccirc%5Ctext%7BC%7D" data-display="false"></span></p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',80,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Asigná primero el extremo más bajo a la partícula menos polarizable; identificá después el puente de H y controlá los electrones.</p><details class="u6Subsolution" open><summary>a) H₂, N₂ y NH₃</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Sustancia</th><th>Razón</th><th>P. Eb. de la consigna</th></tr></thead><tbody><tr><td>H₂</td><td>2 electrones; London muy débil</td><td>−252,8 °C</td></tr><tr><td>N₂</td><td>14 electrones; London mayor</td><td>−185,8 °C</td></tr><tr><td>NH₃</td><td>puentes de H</td><td>−33,3 °C</td></tr></tbody></table></div></div></details><details class="u6Subsolution"><summary>b) CH₄, SiH₄ y AsH₃</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Sustancia</th><th>Razón</th><th>P. Eb. de la consigna</th></tr></thead><tbody><tr><td>CH₄</td><td>10 electrones; London menor</td><td>−161,5 °C</td></tr><tr><td>SiH₄</td><td>18 electrones; London mayor</td><td>−112 °C</td></tr><tr><td>AsH₃</td><td>42 electrones; London y dipolo–dipolo</td><td>−62,5 °C</td></tr></tbody></table></div><aside class="u6Tip"><strong>Para recordar:</strong> La masa y el número de electrones importan: no decidas solo con “polar > apolar”.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.9$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><ol type="a">
<li>En la tabla y el gráfico siguientes se informan los puntos de ebullición (expresados en grados Celsius) de las sustancias que forman los elementos del grupo 14 con hidrógeno: [Sustancia | P. Ebull.: <span class="u6Math" data-latex="CH_4" data-display="false"></span>: <span class="u6Math" data-latex="-162" data-display="false"></span>, <span class="u6Math" data-latex="SiH_4" data-display="false"></span>: <span class="u6Math" data-latex="-112" data-display="false"></span>, <span class="u6Math" data-latex="GeH_4" data-display="false"></span>: <span class="u6Math" data-latex="-88" data-display="false"></span>, <span class="u6Math" data-latex="SnH_4" data-display="false"></span>: <span class="u6Math" data-latex="-52" data-display="false"></span>] ¿Qué interacciones intermoleculares presentan las moléculas de cada uno de estos compuestos entre sí? Identificar la tendencia que presentan estos datos. Explicar la tendencia observada comparando las intensidades relativas de las interacciones intermoleculares presentes en cada sustancia pura en el estado líquido.</li>
<li>En la tabla siguiente se informan los puntos de ebullición de las sustancias que forman los elementos de los grupos 15, 16 y 17 con hidrógeno: [Sustancia | P. Ebull.: <span class="u6Math" data-latex="NH_3" data-display="false"></span>: <span class="u6Math" data-latex="-33" data-display="false"></span>, <span class="u6Math" data-latex="PH_3" data-display="false"></span>: <span class="u6Math" data-latex="-88" data-display="false"></span>, <span class="u6Math" data-latex="AsH_3" data-display="false"></span>: <span class="u6Math" data-latex="-63" data-display="false"></span>, <span class="u6Math" data-latex="SbH_3" data-display="false"></span>: <span class="u6Math" data-latex="-17" data-display="false"></span>; <span class="u6Math" data-latex="H_2O" data-display="false"></span>: <span class="u6Math" data-latex="100" data-display="false"></span>, <span class="u6Math" data-latex="H_2S" data-display="false"></span>: <span class="u6Math" data-latex="-61" data-display="false"></span>, <span class="u6Math" data-latex="H_2Se" data-display="false"></span>: <span class="u6Math" data-latex="-42" data-display="false"></span>, <span class="u6Math" data-latex="H_2Te" data-display="false"></span>: <span class="u6Math" data-latex="-4" data-display="false"></span>; <span class="u6Math" data-latex="HF" data-display="false"></span>: <span class="u6Math" data-latex="20" data-display="false"></span>, <span class="u6Math" data-latex="HCl" data-display="false"></span>: <span class="u6Math" data-latex="-85" data-display="false"></span>, <span class="u6Math" data-latex="HBr" data-display="false"></span>: <span class="u6Math" data-latex="-67" data-display="false"></span>, <span class="u6Math" data-latex="HI" data-display="false"></span>: <span class="u6Math" data-latex="-35" data-display="false"></span>] ¿Qué interacciones intermoleculares presentan las moléculas de cada uno de estos compuestos entre sí? Identificar la tendencia que presentan estos datos. ¿Pueden explicarse estas tendencias mediante el mismo análisis realizado en el ítem (a)? ¿Qué modificaciones es necesario introducir en ese análisis?</li>
</ol></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',90,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Separá primero la serie de moléculas tetraédricas apolares de las familias polares con una anomalía por puente de H.</p><details class="u6Subsolution" open><summary>a) Grupo 14</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Sustancia</th><th>P. Eb. de la consigna</th><th>Interacción</th></tr></thead><tbody><tr><td>CH₄</td><td>−162 °C</td><td>London</td></tr><tr><td>SiH₄</td><td>−112 °C</td><td>London</td></tr><tr><td>GeH₄</td><td>−88 °C</td><td>London</td></tr><tr><td>SnH₄</td><td>−52 °C</td><td>London</td></tr></tbody></table></div><p>Cada hidruro es AX₄ con ligandos iguales, por eso es apolar. Hacia abajo aumentan electrones, polarizabilidad, London y punto de ebullición.</p></div></details><details class="u6Subsolution"><summary>b) Grupos 15, 16 y 17</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Serie</th><th>Descenso sin el primer hidruro</th><th>Primer hidruro y explicación</th></tr></thead><tbody><tr><td>15</td><td>PH₃ (−88) < AsH₃ (−63) < SbH₃ (−17) °C</td><td>NH₃ (−33): además forma puente de H</td></tr><tr><td>16</td><td>H₂S (−61) < H₂Se (−42) < H₂Te (−4) °C</td><td>H₂O (100): red de puentes de H</td></tr><tr><td>17</td><td>HCl (−85) < HBr (−67) < HI (−35) °C</td><td>HF (20): puente de H</td></tr></tbody></table></div><p>Los hidruros de una misma serie tienen London; los polares suman dipolo–dipolo. Al bajar, London aumenta. Para NH₃, H₂O y HF incorporá el puente de H para explicar por qué quedan por encima de la tendencia simple.</p><aside class="u6Tip"><strong>Para recordar:</strong> La intensidad de London y el puente de H actúan en conjunto; “primer elemento = mayor P. Eb.” no siempre describe todos los pares de la serie.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.10$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><ol type="a">
<li>Ordenar de menor a mayor los puntos de ebullición de las sustancias siguientes:</li>
</ol>
<ol type="1">
<li><span class="u6Math" data-latex="SiH_4" data-display="false"></span>, 2) <span class="u6Math" data-latex="H_2S" data-display="false"></span>, 3) <span class="u6Math" data-latex="CH_4" data-display="false"></span>, 4) <span class="u6Math" data-latex="KCl" data-display="false"></span>. Justificar.</li>
</ol>
<ol start="2" type="a">
<li>Ordenar de mayor a menor los puntos de ebullición de las sustancias siguientes:</li>
</ol>
<ol type="1">
<li><span class="u6Math" data-latex="CCl_4" data-display="false"></span>, 2) <span class="u6Math" data-latex="NaCl" data-display="false"></span>, 3) <span class="u6Math" data-latex="Ne" data-display="false"></span>. Justificar.</li>
</ol></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',100,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Primero separá redes iónicas de partículas neutras. Entre moléculas, compará polaridad y polarizabilidad.</p><details class="u6Subsolution" open><summary>a) Menor a mayor</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Orden</th><th>Sustancia</th><th>Motivo</th></tr></thead><tbody><tr><td>1</td><td>CH₄</td><td>10 electrones, apolar; London débil</td></tr><tr><td>2</td><td>SiH₄</td><td>18 electrones, apolar; London mayor</td></tr><tr><td>3</td><td>H₂S</td><td>18 electrones, polar; London + dipolo–dipolo</td></tr><tr><td>4</td><td>KCl</td><td>red iónica; separar cargas requiere mucha energía</td></tr></tbody></table></div><div class="u6Equation"><div class="u6Math" data-latex="%5Cmathrm%7BCH_4%3CSiH_4%3CH_2S%3CKCl%7D" data-display="true"></div></div><p>En la numeración original: 3 < 1 < 2 < 4.</p></div></details><details class="u6Subsolution"><summary>b) Mayor a menor</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Orden</th><th>Sustancia</th><th>Motivo</th></tr></thead><tbody><tr><td>1</td><td>NaCl</td><td>red iónica</td></tr><tr><td>2</td><td>CCl₄</td><td>74 electrones; London considerable</td></tr><tr><td>3</td><td>Ne</td><td>10 electrones; London muy débil</td></tr></tbody></table></div><div class="u6Equation"><div class="u6Math" data-latex="%5Cmathrm%7BNaCl%3ECCl_4%3ENe%7D" data-display="true"></div></div><p>En la numeración original: 2 > 1 > 3.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.11$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Justificar los siguientes hechos experimentales: a) Los compuestos iónicos conducen la corriente eléctrica cuando están fundidos o en solución, pero no lo hacen en estado sólido. b) Los compuestos iónicos generalmente tienen puntos de fusión y de ebullición altos. c) Los compuestos moleculares no son conductores de la electricidad en ningún estado de agregación (sólido, líquido o gaseoso).</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',110,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">El criterio común es identificar partículas y portadores de carga: un enlace fuerte por sí solo no garantiza conducción.</p><details class="u6Subsolution" open><summary>a) ¿Por qué la sal conduce fundida o disuelta?</summary><div><p>En el sólido, cationes y aniones ocupan sitios de la red: hay cargas, pero no se desplazan libremente. Al fundir o disolver una sal soluble, los iones móviles transportan corriente.</p></div></details><details class="u6Subsolution"><summary>b) ¿Por qué su fusión y ebullición suelen ser altas?</summary><div><p>La red atrae cargas opuestas en todas direcciones. Separar sus iones exige una cantidad importante de energía; el valor concreto depende de la sal.</p></div></details><details class="u6Subsolution"><summary>c) ¿Qué ocurre con sustancias moleculares?</summary><div><p>Las moléculas neutras puras carecen en general de portadores móviles, por lo que no conducen en los estados indicados. Una sustancia molecular que ioniza al disolverse en agua puede dar una solución conductora: eso no contradice la frase sobre la sustancia pura.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.12$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>Dados el <span class="u6Math" data-latex="NaBr" data-display="false"></span> y el <span class="u6Math" data-latex="CH_3Br" data-display="false"></span>, responder: a) ¿Cuál de las proposiciones siguientes se refiere a cada uno? 1) Forma una red cristalina que contiene iones de carga opuesta. 2) En estado sólido, líquido o gaseoso está constituido por moléculas. b) ¿Cuál tiene menor punto de fusión? Justificar teniendo en cuenta todas las interacciones involucradas. c) ¿Cuál conduce la corriente eléctrica en solución acuosa? d) ¿Cuál conduce la corriente eléctrica en estado líquido?</p></div>$cbc$,'Serie 6 · Química CBC · Cátedra Di Risio',120,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">NaBr está constituido por iones en una red; CH₃Br, por moléculas con dipolo y fuerzas de London.</p><details class="u6Subsolution" open><summary>a) Estructura</summary><div><div class="u6TableScroll"><table class="u6Table"><thead><tr><th>Proposición</th><th>Sustancia</th><th>Partículas</th></tr></thead><tbody><tr><td>1 · red de cargas opuestas</td><td>NaBr</td><td>Na⁺ y Br⁻</td></tr><tr><td>2 · moléculas</td><td>CH₃Br</td><td>moléculas covalentes discretas</td></tr></tbody></table></div></div></details><details class="u6Subsolution"><summary>b) Menor punto de fusión</summary><div><p><strong>CH₃Br.</strong> Para fundirlo se separan moléculas unidas por London y dipolo–dipolo. Para fundir NaBr hay que desarmar una red iónica.</p></div></details><details class="u6Subsolution"><summary>c) Conducción en agua</summary><div><p><strong>NaBr(aq)</strong>: los iones hidratados se mueven. CH₃Br permanece principalmente molecular y no aporta iones de forma comparable.</p></div></details><details class="u6Subsolution"><summary>d) Conducción en líquido puro</summary><div><p><strong>NaBr fundido</strong>: Na⁺ y Br⁻ son móviles. CH₃Br líquido está formado por moléculas neutras.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',6,'serie-6-interacciones',$cbc$Ejercicio 6.13$cbc$,$cbc$<div class="u6Verbatim" data-source="serie6_teoria_y_ejercicios_resueltos.md"><p>En la tabla siguiente se informan algunas propiedades físicas de las sustancias <span class="u6Math" data-latex="Cl_2" data-display="false"></span>, <span class="u6Math" data-latex="Cu" data-display="false"></span> y <span class="u6Math" data-latex="NaCl" data-display="false"></span>. Ubicar cada sustancia en la fila que se considere adecuada y completar la tabla. (FIM: tipo/s de fuerzas intermoleculares; no aplican para todas las sustancias que deben listarse).</p>
